#pragma once

#include <string>
#include <nlohmann/json.hpp>
#include <vector>
#include <algorithm>
#include <cstdint>

namespace ptv {

struct AccessibilityState {
    // Comfort / locomotion
    float vignette01{0.35f};
    std::string turn_mode{"snap"}; // "snap" | "smooth"
    float smooth_turn_speed_dps{120.0f};
    float snap_turn_degrees{45.0f};
    float flight_assist01{0.5f};

    // Haptics / UI
    float haptics_amp01{1.0f};
    std::string subtitles_size{"medium"}; // small|medium|large
    std::string colorblind_mode{"off"}; // off|protan|deutan|tritan
    float motion_cue_opacity01{0.6f};

    // Seated / calibration
    float seated_height_offset_m{0.0f};

    bool any_changed{false};

    static AccessibilityState from_defaults_json(const nlohmann::json& j) {
        AccessibilityState s;
        if (!j.is_object()) return s;
        s.vignette01              = std::clamp(j.value("vignette_intensity01", s.vignette01), 0.0f, 1.0f);
        s.turn_mode               = j.value("turn_type", s.turn_mode);
        if (s.turn_mode != "snap" && s.turn_mode != "smooth") s.turn_mode = "snap";
        s.smooth_turn_speed_dps   = j.value("turn_speed_deg_per_s", s.smooth_turn_speed_dps);
        s.snap_turn_degrees       = j.value("snap_turn_degrees", s.snap_turn_degrees);
        s.flight_assist01         = std::clamp(j.value("flight_assist01", s.flight_assist01), 0.0f, 1.0f);
        s.haptics_amp01           = std::clamp(j.value("haptics_amp01", s.haptics_amp01), 0.0f, 1.0f);
        s.subtitles_size          = j.value("subtitles_size", s.subtitles_size);
        s.colorblind_mode         = j.value("colorblind_mode", s.colorblind_mode);
        s.seated_height_offset_m  = j.value("seated_height_offset_m", s.seated_height_offset_m);
        s.motion_cue_opacity01    = std::clamp(j.value("motion_cue_opacity01", s.motion_cue_opacity01), 0.0f, 1.0f);
        return s;
    }

    nlohmann::json to_json() const {
        nlohmann::json j;
        j["vignette_intensity01"] = vignette01;
        j["turn_type"] = turn_mode;
        j["turn_speed_deg_per_s"] = smooth_turn_speed_dps;
        j["snap_turn_degrees"] = snap_turn_degrees;
        j["flight_assist01"] = flight_assist01;
        j["haptics_amp01"] = haptics_amp01;
        j["subtitles_size"] = subtitles_size;
        j["colorblind_mode"] = colorblind_mode;
        j["seated_height_offset_m"] = seated_height_offset_m;
        j["motion_cue_opacity01"] = motion_cue_opacity01;
        return j;
    }
};

inline void apply_updates_from_params(AccessibilityState& s, const nlohmann::json& j) {
    if (!j.is_object()) return;
    auto clamp01 = [](float v){ return std::clamp(v, 0.0f, 1.0f); };

    auto upd_f = [&](const char* key, float& dst, bool clamp=false){
        if (j.contains(key)) { float nv = j.at(key).get<float>(); if (clamp) nv = clamp01(nv); if (nv != dst) { dst = nv; s.any_changed = true; } }
    };
    auto upd_s = [&](const char* key, std::string& dst, std::vector<std::string> allowed = {}){
        if (j.contains(key)) {
            std::string nv = j.at(key).get<std::string>();
            if (!allowed.empty()) {
                if (std::find(allowed.begin(), allowed.end(), nv) == allowed.end()) return; // ignore invalid
            }
            if (nv != dst) { dst = nv; s.any_changed = true; }
        }
    };

    upd_f("set_vignette01", s.vignette01, true);
    upd_s("set_turn_type", s.turn_mode, {"snap","smooth"});
    upd_f("set_turn_speed_dps", s.smooth_turn_speed_dps, false);
    upd_f("set_snap_degrees", s.snap_turn_degrees, false);
    upd_f("set_flight_assist01", s.flight_assist01, true);
    upd_f("set_haptics_amp01", s.haptics_amp01, true);
    upd_s("set_subtitles_size", s.subtitles_size, {"small","medium","large"});
    upd_s("set_colorblind_mode", s.colorblind_mode, {"off","protan","deutan","tritan"});
    if (j.contains("nudge_seated_height_m")) { s.seated_height_offset_m += j.at("nudge_seated_height_m").get<float>(); s.any_changed = true; }
    upd_f("set_seated_height_m", s.seated_height_offset_m, false);
    upd_f("set_motion_cue_opacity01", s.motion_cue_opacity01, true);
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>
#include <vector>
#include <utility>

#include "accessibility_shared.h"

namespace ptv {

static inline void push_tag(World& w, std::uint32_t e, const std::string& s) {
    if (!w.has<CTag>(e)) { w.emplace_or_replace<CTag>(e, CTag{}); }
    auto& tag = w.get<CTag>(e);
    tag.tags.emplace_back(s);
}

class AccessibilitySettings : public IMechanic {
public:
    void on_attach(World& w, std::uint32_t e, const nlohmann::json& params) override {
        state_ = AccessibilityState::from_defaults_json(params);
        entity_ = e;
        // Register Wrist Menu page (via HUD contract)
        nlohmann::json jpage; jpage["id"] = "accessibility"; jpage["title"] = "Accessibility & Comfort"; jpage["order"] = 20;
        push_tag(w, e, std::string("ui.page.register:") + jpage.dump());
        // Apply defaults immediately
        publish_all(w, e, /*with_toast=*/true);
        // Optionally persist immediately if params request it
        if (params.value("persist_on_attach", false)) {
            persist_now(w, e, "init");
        }
    }

    void on_update(World& w, std::uint32_t e, float) override;

    void on_detach(World&, std::uint32_t) override {}

    std::string id() const override { return "generated.accessibility_settings"; }

private:
    void publish_all(World& w, std::uint32_t e, bool with_toast) {
        // Comfort vignette (shared prefix from locomotion_options_ui)
        {
            nlohmann::json j; j["intensity01"] = state_.vignette01; j["ttl"] = 0.2f;
            push_tag(w, e, std::string("comfort.vignette:") + j.dump());
        }
        // Turn settings (shared with locomotion systems)
        {
            nlohmann::json j; j["mode"] = state_.turn_mode; j["speed_dps"] = state_.smooth_turn_speed_dps; j["snap_degrees"] = state_.snap_turn_degrees;
            push_tag(w, e, std::string("locomotion.turn:") + j.dump());
        }
        // Flight assist broadcast (for flight/hover comfort modules)
        {
            nlohmann::json j; j["assist01"] = state_.flight_assist01;
            push_tag(w, e, std::string("flight.assist:") + j.dump());
        }
        // Haptics overall amplitude setting (consumed by haptics manager or mechanics honoring it)
        {
            nlohmann::json j; j["amp01"] = state_.haptics_amp01;
            push_tag(w, e, std::string("haptics.settings:") + j.dump());
        }
        // Subtitles size + colorblind mode (HUD may consume)
        {
            nlohmann::json j; j["size"] = state_.subtitles_size; push_tag(w, e, std::string("ui.subtitles:") + j.dump());
        }
        {
            nlohmann::json j; j["mode"] = state_.colorblind_mode; push_tag(w, e, std::string("ui.colorblind:") + j.dump());
        }
        // Seated height calibration
        {
            nlohmann::json j; j["meters"] = state_.seated_height_offset_m;
            push_tag(w, e, std::string("player.height_offset:") + j.dump());
        }
        // Motion cues opacity (for overlays, speed lines, etc.)
        {
            nlohmann::json j; j["opacity01"] = state_.motion_cue_opacity01;
            push_tag(w, e, std::string("ui.motion_cue:") + j.dump());
        }
        if (with_toast) {
            nlohmann::json j; j["text"] = std::string("Applied Accessibility & Comfort"); j["ttl"] = 1.0f;
            push_tag(w, e, std::string("ui.toast:") + j.dump());
        }
    }

    void persist_now(World& w, std::uint32_t e, const std::string& reason) {
        nlohmann::json sec; sec["section"] = "accessibility"; sec["data"] = state_.to_json();
        push_tag(w, e, std::string("save.section.push:") + sec.dump());
        nlohmann::json req; req["reason"] = reason; req["who"] = "generated.accessibility_settings";
        push_tag(w, e, std::string("save.request:") + req.dump());
    }

private:
    AccessibilityState state_{};
    std::uint32_t entity_{0};
};

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.accessibility_settings", ptv::AccessibilitySettings)

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>
#include <vector>

#include "accessibility_shared.h"

namespace ptv {

extern void push_tag(World& w, std::uint32_t e, const std::string& s);

// Helper: fetch this mechanic's live params_json from CMechanicBinding
static nlohmann::json get_live_params(World& w, std::uint32_t e, const std::string& mech_id) {
    if (!w.has<CMechanicBinding>(e)) return nlohmann::json{};
    auto& mb = w.get<CMechanicBinding>(e);
    for (const auto& entry : mb.entries) {
        if (entry.id == mech_id || entry.builtin_id == mech_id) {
            auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
            if (j.is_discarded()) return nlohmann::json{};
            return j;
        }
    }
    return nlohmann::json{};
}

void AccessibilitySettings::on_update(World& w, std::uint32_t e, float) {
    // Read live controls coming from Wrist Menu or tests via our own binding entry
    auto j = get_live_params(w, e, id());

    // Track whether we should persist this frame
    bool request_save = false;
    bool menu_closed_persist = false;

    if (j.is_object()) {
        // Apply incoming updates to state_
        state_.any_changed = false;
        apply_updates_from_params(state_, j);

        request_save = j.value("request_save", false);
        menu_closed_persist = j.value("menu_closed", false); // tests/hud can set this on close

        // If any setting changed, publish appropriate tags immediately
        if (state_.any_changed) {
            // publish deltas (for simplicity publish all)
            publish_all(w, e, /*with_toast=*/false);
        }
    }

    if (request_save || menu_closed_persist) {
        persist_now(w, e, request_save ? std::string("explicit_request") : std::string("menu_close"));
        // small UX toast
        nlohmann::json jt; jt["text"] = std::string("Accessibility settings saved"); jt["ttl"] = 1.0f;
        push_tag(w, e, std::string("ui.toast:") + jt.dump());
    }
}

} // namespace ptv
